arguments.content:
#!/usr/bin/env node
'use strict';

/*
 * extract.js - extract memory values from a compiled ELF binary.
 *
 * Usage: node extract.js /app/a.out > out.json
 *
 * The ELF program headers (PT_LOAD segments) describe where each part of the
 * file is mapped into memory. We rebuild that memory image:
 *   - a classic executable (ET_EXEC) is loaded at 0x400000, so its segment
 *     virtual addresses (already 0x400000-based) are used as-is;
 *   - a position-independent executable (ET_DYN) has 0-based virtual
 *     addresses and is loaded at the conventional base 0x400000.
 *
 * Every complete 4-byte little-endian word within a loaded segment is
 * emitted as { "<address>": <unsigned integer value> }.
 */

const fs = require('fs');

const ET_EXEC = 2;
const ET_DYN = 3;
const PT_LOAD = 1;
const LOAD_BASE = 0x400000;

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }

  const buf = fs.readFileSync(path);

  if (buf.length < 64 || buf[0] !== 0x7f || buf.toString('ascii', 1, 4) !== 'ELF') {
    process.stderr.write('error: not an ELF binary\n');
    process.exit(1);
  }

  const is64 = buf[4] === 2;
  const isLittle = buf[5] === 1;
  if (!isLittle) {
    process.stderr.write('error: only little-endian ELFs are supported\n');
    process.exit(1);
  }

  const e_type = buf.readUInt16LE(16);
  const e_phoff = is64 ? Number(buf.readBigUInt64LE(32)) : buf.readUInt32LE(28);
  const e_phentsize = buf.readUInt16LE(54);
  const e_phnum = buf.readUInt16LE(56);

  // Classic executables already carry 0x400000-based addresses; PIEs start
  // at 0 and are mapped at the conventional 0x400000 base.
  const base = e_type === ET_DYN ? LOAD_BASE : 0;

  const words = new Map();

  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;

    const p_type = buf.readUInt32LE(off);
    if (p_type !== PT_LOAD) continue;

    let p_offset, p_vaddr, p_filesz;
    if (is64) {
      p_offset = Number(buf.readBigUInt64LE(off + 8));
      p_vaddr = Number(buf.readBigUInt64LE(off + 16));
      p_filesz = Number(buf.readBigUInt64LE(off + 32));
    } else {
      p_offset = buf.readUInt32LE(off + 4);
      p_vaddr = buf.readUInt32LE(off + 8);
      p_filesz = buf.readUInt32LE(off + 16);
    }

    const avail = Math.min(p_filesz, buf.length - p_offset);
    for (let j = 0; j + 4 <= avail; j += 4) {
      const addr = base + p_vaddr + j;
      words.set(addr, buf.readUInt32LE(p_offset + j));
    }
  }

  const out = {};
  for (const addr of [...words.keys()].sort((a, b) => a - b)) {
    out[String(addr)] = words.get(addr);
  }

  process.stdout.write(JSON.stringify(out) + '\n');
}

main();
